package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class Node_absUrl_TriageGen1Test {

    private Node node;
    private URL baseUri;

    @Before
    public void setUp() throws Exception {
        baseUri = new URL("http://example.com/");
        Attributes attributes = mock(Attributes.class);
        node = mock(Node.class);
        when(node.baseUri()).thenReturn(baseUri.toExternalForm());
        when(node.attr(anyString())).thenReturn(null);
        when(node.hasAttr(anyString())).thenReturn(false);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAbsUrlWithEmptyAttributeKey() {
        node.absUrl("");
    }

    @Test
    public void testAbsUrlWithNoAttributeKey() {
        when(node.attr("href")).thenReturn("http://example.com/test");
        when(node.hasAttr("href")).thenReturn(true);
        String result = node.absUrl("href");
        assertEquals("http://example.com/test", result);
    }

    @Test
    public void testAbsUrlWithRelativeUrl() {
        when(node.attr("href")).thenReturn("/test");
        when(node.hasAttr("href")).thenReturn(true);
        String result = node.absUrl("href");
        assertEquals("http://example.com/test", result);
    }

    @Test
    public void testAbsUrlWithFullPath() {
        when(node.attr("href")).thenReturn("http://another.com/test");
        when(node.hasAttr("href")).thenReturn(true);
        String result = node.absUrl("href");
        assertEquals("http://another.com/test", result);
    }

    @Test
    public void testAbsUrlWithMalformedBaseUri() {
        when(node.baseUri()).thenReturn("htp://malformed/");
        when(node.attr("href")).thenReturn("/test");
        when(node.hasAttr("href")).thenReturn(true);
        String result = node.absUrl("href");
        assertEquals("http://malformed/test", result);
    }

    @Test
    public void testAbsUrlWithMalformedRelativeUrl() {
        when(node.attr("href")).thenReturn("htp://malformed/");
        when(node.hasAttr("href")).thenReturn(true);
        String result = node.absUrl("href");
        assertEquals("htp://malformed/", result);
    }

    @Test
    public void testAbsUrlWithEmptyAttribute() {
        when(node.attr("href")).thenReturn("");
        when(node.hasAttr("href")).thenReturn(false);
        String result = node.absUrl("href");
        assertTrue(result.isEmpty());
    }

    @Test
    public void testAbsUrlWithNullAttribute() {
        when(node.attr("href")).thenReturn(null);
        when(node.hasAttr("href")).thenReturn(false);
        String result = node.absUrl("href");
        assertTrue(result.isEmpty());
    }

    @Test
    public void testAbsUrlWithNullAttributeKey() {
        String result = node.absUrl(null);
        assertTrue(result.isEmpty());
    }
}
